use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

/// Precondition from the node contract: len(question) <= 512 (characters).
const MAX_QUESTION_CHARS: usize = 512;
/// Bound on tool-orchestration rounds per run.
const MAX_ROUNDS: usize = 4;
/// Bound on the number of lookup hits folded into the prompt per round.
const MAX_HITS: usize = 8;
/// Bound on the bytes of lookup results folded into the prompt per round.
const MAX_OBSERVATION_BYTES: usize = 4096;
/// The only tool in this node's scope.
const TOOL_LOOKUP: &str = "lookup";

const SYSTEM: &str = "You answer customer support questions using the provided context. \
You may call the `lookup` tool to search the knowledge base when the context is insufficient. \
Answer concisely.";

fn intent_label(i: Intent) -> &'static str {
    match i {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn error_result(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn truncate_utf8(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut end = max;
        while !s.is_char_boundary(end) {
            end -= 1;
        }
        s.truncate(end);
    }
    s
}

fn render_hits(hits: &[String]) -> String {
    if hits.is_empty() {
        return String::from("(no results)");
    }
    let mut out = String::new();
    for hit in hits.iter().take(MAX_HITS) {
        if out.len() >= MAX_OBSERVATION_BYTES {
            break;
        }
        out.push_str(hit);
        out.push('\n');
    }
    truncate_utf8(out, MAX_OBSERVATION_BYTES)
}

fn build_prompt(ctx: &ConversationContext, observations: &[String]) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\n\nQuestion:\n");
    p.push_str(&ctx.question);
    p.push('\n');

    if !ctx.knowledge.is_empty() {
        p.push_str("\nContext:\n");
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }

    for (i, obs) in observations.iter().enumerate() {
        p.push_str(&format!("\nLookup result {}:\n", i + 1));
        p.push_str(obs);
    }
    p
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The contract's requires holds for every input; this check is defensive
        // and only ever yields an error value, never a widened output.
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return error_result("question exceeds 512 characters");
        }

        let mut observations: Vec<String> = Vec::new();

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&ctx, &observations);
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != TOOL_LOOKUP {
                        return error_result("requested tool is not in scope");
                    }
                    let hits = kb_read::lookup(&req.query);
                    observations.push(render_hits(&hits));
                }
            }
        }

        error_result("tool-call budget exhausted without a final answer")
    }
}

export!(Node);
